-- 003 - Copy existing rows from the legacy farm_records table into the domain tables
-- (generated by scripts/generate-sql.js - do not edit by hand).
-- Safe to run more than once. Rows that already exist are left alone, and farm_records itself is
-- NOT modified or dropped, so you can verify first. The last query compares row counts per type;
-- if legacy_rows and new_rows differ, inspect those rows before dropping farm_records.
-- Rows are skipped when their id is not a UUID (non-holiday records), when a required number or
-- date is missing, or when a value would break a CHECK constraint.

create or replace function public.fw_try_numeric(v text) returns numeric language plpgsql immutable as $$
begin return nullif(btrim(v), '')::numeric; exception when others then return null; end; $$;
create or replace function public.fw_try_int(v text) returns integer language plpgsql immutable as $$
begin return round(nullif(btrim(v), '')::numeric)::integer; exception when others then return null; end; $$;
create or replace function public.fw_try_date(v text) returns date language plpgsql immutable as $$
begin return nullif(btrim(v), '')::date; exception when others then return null; end; $$;
create or replace function public.fw_try_uuid(v text) returns uuid language plpgsql immutable as $$
begin return nullif(btrim(v), '')::uuid; exception when others then return null; end; $$;
create or replace function public.fw_try_bool(v text, fallback boolean) returns boolean language sql immutable as $$
  select case lower(btrim(coalesce(v, '')))
    when 'true' then true when 't' then true
    when 'false' then false when 'f' then false
    else fallback end;
$$;

-- crop-fields
insert into public.crop_fields (id, farm_id, created_by, name, size, unit, soil_type, notes, extra, created_at, updated_at)
select public.fw_try_uuid(r.record_id),
       r.farm_id,
       r.user_id,
       coalesce(r.data ->> 'name', ''),
       public.fw_try_numeric(r.data ->> 'size'),
       coalesce(r.data ->> 'unit', ''),
       coalesce(r.data ->> 'soilType', ''),
       coalesce(r.data ->> 'notes', ''),
       coalesce(r.data, '{}'::jsonb) - array['id', 'createdAt', 'updatedAt', 'name', 'size', 'unit', 'soilType', 'notes']::text[],
       r.created_at,
       r.updated_at
from public.farm_records r
where r.record_type = 'crop-fields'
  and public.fw_try_uuid(r.record_id) is not null
  and public.fw_try_numeric(r.data ->> 'size') is not null
  and (public.fw_try_numeric(r.data ->> 'size') is null or public.fw_try_numeric(r.data ->> 'size') >= 0)
on conflict (farm_id, id) do nothing;

-- planting-seasons
insert into public.planting_seasons (id, farm_id, created_by, name, start_date, end_date, notes, extra, created_at, updated_at)
select public.fw_try_uuid(r.record_id),
       r.farm_id,
       r.user_id,
       coalesce(r.data ->> 'name', ''),
       public.fw_try_date(r.data ->> 'startDate'),
       public.fw_try_date(r.data ->> 'endDate'),
       coalesce(r.data ->> 'notes', ''),
       coalesce(r.data, '{}'::jsonb) - array['id', 'createdAt', 'updatedAt', 'name', 'startDate', 'endDate', 'notes']::text[],
       r.created_at,
       r.updated_at
from public.farm_records r
where r.record_type = 'planting-seasons'
  and public.fw_try_uuid(r.record_id) is not null
  and public.fw_try_date(r.data ->> 'startDate') is not null
  and public.fw_try_date(r.data ->> 'endDate') is not null
  and public.fw_try_date(r.data ->> 'endDate') >= public.fw_try_date(r.data ->> 'startDate')
on conflict (farm_id, id) do nothing;

-- crops
insert into public.crops (id, farm_id, created_by, name, variety, type, status, field_id, planted_date, harvest_date, planting_season_id, related_record, notes, extra, created_at, updated_at)
select public.fw_try_uuid(r.record_id),
       r.farm_id,
       r.user_id,
       coalesce(r.data ->> 'name', ''),
       coalesce(r.data ->> 'variety', ''),
       coalesce(r.data ->> 'type', ''),
       coalesce(r.data ->> 'status', ''),
       (select x.id from public.crop_fields x where x.farm_id = r.farm_id and x.id = public.fw_try_uuid(r.data ->> 'field')),
       public.fw_try_date(r.data ->> 'plantedDate'),
       public.fw_try_date(r.data ->> 'harvestDate'),
       (select x.id from public.planting_seasons x where x.farm_id = r.farm_id and x.id = public.fw_try_uuid(r.data ->> 'plantingSeason')),
       coalesce(nullif(r.related_record_id, ''), r.data ->> 'relatedRecord', ''),
       coalesce(r.data ->> 'notes', ''),
       coalesce(r.data, '{}'::jsonb) - array['id', 'createdAt', 'updatedAt', 'name', 'variety', 'type', 'status', 'field', 'plantedDate', 'harvestDate', 'plantingSeason', 'relatedRecord', 'notes']::text[],
       r.created_at,
       r.updated_at
from public.farm_records r
where r.record_type = 'crops'
  and public.fw_try_uuid(r.record_id) is not null
  and public.fw_try_date(r.data ->> 'plantedDate') is not null
on conflict (farm_id, id) do nothing;

