-- Verification: legacy rows vs migrated rows
select * from (
  select 'crop-fields' as record_type,
         (select count(*) from public.farm_records where record_type = 'crop-fields') as legacy_rows,
         (select count(*) from public.crop_fields) as new_rows
  union all
  select 'planting-seasons' as record_type,
         (select count(*) from public.farm_records where record_type = 'planting-seasons') as legacy_rows,
         (select count(*) from public.planting_seasons) as new_rows
  union all
  select 'crops' as record_type,
         (select count(*) from public.farm_records where record_type = 'crops') as legacy_rows,
         (select count(*) from public.crops) as new_rows
  union all
  select 'bee-hive-types' as record_type,
         (select count(*) from public.farm_records where record_type = 'bee-hive-types') as legacy_rows,
         (select count(*) from public.bee_hive_types) as new_rows
  union all
  select 'bee-hives' as record_type,
         (select count(*) from public.farm_records where record_type = 'bee-hives') as legacy_rows,
         (select count(*) from public.bee_hives) as new_rows
  union all
  select 'bee-colonies' as record_type,
         (select count(*) from public.farm_records where record_type = 'bee-colonies') as legacy_rows,
         (select count(*) from public.bee_colonies) as new_rows
  union all
  select 'hive-inspections' as record_type,
         (select count(*) from public.farm_records where record_type = 'hive-inspections') as legacy_rows,
         (select count(*) from public.hive_inspections) as new_rows
  union all
  select 'honey-productions' as record_type,
         (select count(*) from public.farm_records where record_type = 'honey-productions') as legacy_rows,
         (select count(*) from public.honey_productions) as new_rows
  union all
  select 'animal-fields' as record_type,
         (select count(*) from public.farm_records where record_type = 'animal-fields') as legacy_rows,
         (select count(*) from public.animal_fields) as new_rows
  union all
  select 'livestock-groups' as record_type,
         (select count(*) from public.farm_records where record_type = 'livestock-groups') as legacy_rows,
         (select count(*) from public.livestock_groups) as new_rows
  union all
  select 'animals' as record_type,
         (select count(*) from public.farm_records where record_type = 'animals') as legacy_rows,
         (select count(*) from public.animals) as new_rows
  union all
  select 'feed-mixtures' as record_type,
         (select count(*) from public.farm_records where record_type = 'feed-mixtures') as legacy_rows,
         (select count(*) from public.feed_mixtures) as new_rows
  union all
  select 'financial-records' as record_type,
         (select count(*) from public.farm_records where record_type = 'financial-records') as legacy_rows,
         (select count(*) from public.financial_records) as new_rows
  union all
  select 'users' as record_type,
         (select count(*) from public.farm_records where record_type = 'users') as legacy_rows,
         (select count(*) from public.system_users) as new_rows
  union all
  select 'farm-workers' as record_type,
         (select count(*) from public.farm_records where record_type = 'farm-workers') as legacy_rows,
         (select count(*) from public.farm_workers) as new_rows
  union all
  select 'tasks' as record_type,
         (select count(*) from public.farm_records where record_type = 'tasks') as legacy_rows,
         (select count(*) from public.tasks) as new_rows
  union all
  select 'worker-leaves' as record_type,
         (select count(*) from public.farm_records where record_type = 'worker-leaves') as legacy_rows,
         (select count(*) from public.worker_leaves) as new_rows
  union all
  select 'holidays' as record_type,
         (select count(*) from public.farm_records where record_type = 'holidays') as legacy_rows,
         (select count(*) from public.holidays) as new_rows
) counts
order by record_type;

